<?php
declare(strict_types=1);
require_once __DIR__ . '/_layout.php';
$db=admin_db();admin_require_auth();
if($_SERVER['REQUEST_METHOD']==='POST'){
    admin_verify_csrf();$id=(int)($_POST['id']??0);$action=(string)($_POST['action']??'');
    if($id&&in_array($action,['new','read','archived'],true)){$db->prepare('UPDATE contact_messages SET status=? WHERE id=?')->execute([$action,$id]);admin_flash('success','Message status updated.');admin_redirect('messages.php?id='.$id);}
    if($id&&$action==='delete'){$db->prepare('DELETE FROM contact_messages WHERE id=?')->execute([$id]);admin_flash('success','Message permanently deleted.');admin_redirect('messages.php');}
}
$filter=(string)($_GET['status']??'all');$allowed=['all','new','read','archived'];if(!in_array($filter,$allowed,true))$filter='all';
if($filter==='all'){$rows=$db->query('SELECT * FROM contact_messages ORDER BY created_at DESC')->fetchAll();}else{$stmt=$db->prepare('SELECT * FROM contact_messages WHERE status=? ORDER BY created_at DESC');$stmt->execute([$filter]);$rows=$stmt->fetchAll();}
$selected=null;if((int)($_GET['id']??0)){$stmt=$db->prepare('SELECT * FROM contact_messages WHERE id=?');$stmt->execute([(int)$_GET['id']]);$selected=$stmt->fetch()?:null;}
admin_header('Inquiry inbox','messages');
?><div class="actions" style="margin:0 0 15px"><?php foreach($allowed as $item):?><a class="button small <?=$filter===$item?'':'secondary'?>" href="?status=<?=$item?>"><?=ucfirst($item)?></a><?php endforeach;?></div><div class="split"><section class="panel" style="margin-top:0"><div class="panel-head"><h2>Messages</h2><span class="muted"><?=count($rows)?> shown</span></div><?php if(!$rows):?><div class="empty">No messages in this view.</div><?php else:?><div class="table-wrap"><table><thead><tr><th>From</th><th>Service</th><th>Status</th><th>Date</th></tr></thead><tbody><?php foreach($rows as $row):?><tr><td><a href="?status=<?=admin_e($filter)?>&id=<?=(int)$row['id']?>"><strong><?=admin_e((string)$row['name'])?></strong></a><br><span class="muted"><?=admin_e((string)$row['email'])?></span></td><td><?=admin_e((string)$row['service'])?></td><td><span class="status <?=admin_e((string)$row['status'])?>"><?=admin_e((string)$row['status'])?></span></td><td><?=admin_e(date('M j',strtotime((string)$row['created_at'])))?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section><aside class="panel" style="margin-top:0"><?php if(!$selected):?><div class="empty">Select a message to read it.</div><?php else:?><div class="panel-head"><div><h2><?=admin_e((string)$selected['name'])?></h2><span class="muted"><?=admin_e(date('M j, Y · g:i a',strtotime((string)$selected['created_at'])))?></span></div><span class="status <?=admin_e((string)$selected['status'])?>"><?=admin_e((string)$selected['status'])?></span></div><p><strong>Email</strong><br><a href="mailto:<?=admin_e((string)$selected['email'])?>"><?=admin_e((string)$selected['email'])?></a></p><?php if($selected['phone']):?><p><strong>Phone</strong><br><a href="tel:<?=admin_e((string)$selected['phone'])?>"><?=admin_e((string)$selected['phone'])?></a></p><?php endif;?><?php if($selected['company']):?><p><strong>Company</strong><br><?=admin_e((string)$selected['company'])?></p><?php endif;?><p><strong>Service</strong><br><?=admin_e((string)$selected['service'])?></p><div class="message-body"><?=admin_e((string)$selected['message'])?></div><div class="actions"><a class="button acid" href="mailto:<?=admin_e((string)$selected['email'])?>?subject=Re:%20Your%20Nivra%20inquiry">Reply by email</a><?php foreach(['read','new','archived'] as $status):?><form method="post"><input type="hidden" name="csrf_token" value="<?=admin_csrf()?>"><input type="hidden" name="id" value="<?=(int)$selected['id']?>"><input type="hidden" name="action" value="<?=$status?>"><button class="button secondary small" type="submit">Mark <?=$status?></button></form><?php endforeach;?><form method="post"><input type="hidden" name="csrf_token" value="<?=admin_csrf()?>"><input type="hidden" name="id" value="<?=(int)$selected['id']?>"><input type="hidden" name="action" value="delete"><button class="button danger small" type="submit" data-confirm="Permanently delete this message?">Delete</button></form></div><?php endif;?></aside></div><?php admin_footer();?>
